const firstNames = [
    "Rahul", "Amit", "Priya", "Neha", "John",
    "David", "Ankit", "Sneha", "Michael", "Rohit",
    "Pooja", "Vikas", "Karan", "Riya", "Arjun",
    "Sanjay", "Kavita", "Nikhil", "Simran", "Raj"
];

const lastNames = [
    "Sharma", "Verma", "Singh", "Gupta", "Kumar",
    "Patel", "Wilson", "Brown", "Malhotra", "Mehta",
    "Agarwal", "Yadav", "Mishra", "Shah", "Joshi"
];

const jobTypes = [
    "FULL_TIME",
    "PART_TIME",
    "CONTRACT",
    "INTERN",
    "FREELANCE"
];

const designations = [
    "Software Engineer",
    "Senior Developer",
    "Project Manager",
    "Business Analyst",
    "HR Manager",
    "Team Lead",
    "QA Engineer",
    "System Administrator",
    "UI UX Designer",
    "DevOps Engineer",
    "Technical Lead",
    "Data Analyst",
    "Product Manager",
    "Network Engineer"
];

const departments = [
    "IT", "HR", "FINANCE", "MARKETING",
    "SALES", "OPERATIONS", "ADMIN",
    "SUPPORT", "DEVELOPMENT", "TESTING",
    "SECURITY", "ENGINEERING"
];

const cities = [
    "Kanpur", "Delhi", "Mumbai", "Bangalore",
    "Hyderabad", "Chennai", "Pune", "Lucknow",
    "Noida", "Kolkata", "Jaipur", "Ahmedabad",
    "Indore", "Bhopal", "Nagpur", "Surat"
];

const streets = [
    "MG Road", "Civil Lines", "Park Street",
    "Station Road", "Gandhi Nagar",
    "Ashok Nagar", "Model Town",
    "Shastri Nagar", "Nehru Road",
    "Green Avenue", "Lake View Road"
];

function randomItem(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
}

function randomNumber(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Generate employee name
const firstName = randomItem(firstNames);
const lastName = randomItem(lastNames);
const fullName = firstName + " " + lastName;

const email = (firstName + "." + lastName + "." + Date.now() + "@sugya.com").toLowerCase();

// Generate random address
const city = randomItem(cities);
const street = randomItem(streets);

const employee = {
    name: fullName,
    email: email,
    jobType: randomItem(jobTypes),
    designation: randomItem(designations),
    department: randomItem(departments),
    salary: randomNumber(10000, 300000),
    address: {
        address: randomNumber(1, 999) + " " + street + ", " + city
    }
};

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = employee;

return msg;
